window.VOCAB = [
  { n: 2, word: "abstract", pos: "adjective", pron: "ab-STRAKT", def: "Existing as an idea rather than as something physical or concrete.", ex: "Justice is an abstract concept, but its effects are very real.", syn: ["theoretical", "conceptual", "intangible"], ant: ["concrete", "tangible"] },
  { n: 3, word: "acclaim", pos: "verb; also noun", pron: "uh-KLAYM", def: "To praise enthusiastically and publicly; enthusiastic public praise.", ex: "Critics acclaimed her debut album as the best of the year.", syn: ["praise", "applaud", "hail"], ant: ["criticize", "condemn"] },
  { n: 4, word: "adulation", pos: "noun", pron: "aj-uh-LAY-shun", def: "Excessive admiration or praise.", ex: "The young star struggled to stay grounded amid the fans' adulation.", syn: ["worship", "idolization", "flattery"], ant: ["contempt", "scorn"] },
  { n: 5, word: "adversary", pos: "noun", pron: "AD-vur-sair-ee", def: "An opponent or enemy.", ex: "The two chess players had been adversaries for over a decade.", syn: ["opponent", "rival", "foe"], ant: ["ally", "friend"] },
  { n: 6, word: "adversity", pos: "noun", pron: "ad-VUR-sih-tee", def: "Difficulty or misfortune; hard times.", ex: "She kept her sense of humor even in the face of adversity.", syn: ["hardship", "misfortune", "trouble"], ant: ["prosperity", "good fortune"] },
  { n: 7, word: "advocate", pos: "verb; also noun", pron: "AD-vuh-kayt (v.) / AD-vuh-kit (n.)", def: "To publicly support or recommend; a person who supports a cause.", ex: "The nurse advocated for longer breaks for hospital staff.", syn: ["champion", "promote", "supporter"], ant: ["oppose", "opponent"], root: "Latin vocare = to call (calling out in support)" },
  { n: 8, word: "aesthetic", pos: "adjective", pron: "es-THET-ik", def: "Concerned with beauty or the appreciation of beauty.", ex: "The architect cared as much about the building's aesthetic appeal as its function.", syn: ["artistic", "visual", "tasteful"], ant: ["unattractive", "ugly"] },
  { n: 9, word: "affirmation", pos: "noun", pron: "af-ur-MAY-shun", def: "A statement that something is true; emotional support or encouragement.", ex: "The coach's quiet affirmation gave him the confidence to keep going.", syn: ["declaration", "assertion", "endorsement"], ant: ["denial", "rejection"] },
  { n: 10, word: "alleviate", pos: "verb", pron: "uh-LEE-vee-ayt", def: "To make suffering or a problem less severe.", ex: "A cold compress can help alleviate the swelling.", syn: ["ease", "relieve", "lessen"], ant: ["aggravate", "worsen"], root: "lev- = light (lightening a burden)" },
  { n: 11, word: "allusion", pos: "noun", pron: "uh-LOO-zhun", def: "An indirect reference to something, often a famous work or event.", ex: "Calling the new mall a \"labyrinth\" is an allusion to Greek mythology.", syn: ["reference", "mention", "hint"], ant: [] },
  { n: 12, word: "altruistic", pos: "adjective", pron: "al-troo-IS-tik", def: "Showing selfless concern for the well-being of others.", ex: "Donating a kidney to a stranger is a profoundly altruistic act.", syn: ["selfless", "unselfish", "generous"], ant: ["selfish", "egotistic"], root: "alter- = other (concern for others)" },
  { n: 13, word: "ambiguous", pos: "adjective", pron: "am-BIG-yoo-us", def: "Open to more than one interpretation; unclear.", ex: "The text message was so ambiguous that I couldn't tell if she was joking.", syn: ["unclear", "vague", "equivocal"], ant: ["clear", "explicit"], root: "ambi- = both (could go either way)" },
  { n: 14, word: "ambivalence", pos: "noun", pron: "am-BIV-uh-lunce", def: "Having mixed or contradictory feelings about something.", ex: "His ambivalence about college showed in his half-finished applications.", syn: ["uncertainty", "indecision", "conflict"], ant: ["certainty", "conviction"], root: "ambi- = both" },
  { n: 15, word: "anarchy", pos: "noun", pron: "AN-ur-kee", def: "A state of disorder due to the absence of authority or government.", ex: "When the teacher left the room, the class descended into anarchy.", syn: ["chaos", "lawlessness", "disorder"], ant: ["order", "government"], root: "an- = without; arch- = ruler" },
  { n: 16, word: "anecdote", pos: "noun", pron: "AN-ik-doht", def: "A short, often amusing story about a real person or event.", ex: "Grandpa opened his speech with an anecdote about his first job.", syn: ["story", "tale", "account"], ant: [] },
  { n: 17, word: "apathy", pos: "noun", pron: "AP-uh-thee", def: "Lack of interest, enthusiasm, or concern.", ex: "Widespread apathy meant only a handful of students voted for class president.", syn: ["indifference", "disinterest", "unconcern"], ant: ["enthusiasm", "passion"], root: "a- = without; path- = feeling" },
  { n: 18, word: "arbitrary", pos: "adjective", pron: "AR-bih-trair-ee", def: "Based on random choice or personal whim rather than reason.", ex: "The 9 p.m. curfew felt arbitrary since no one explained it.", syn: ["random", "capricious", "unreasoned"], ant: ["rational", "reasoned"] },
  { n: 19, word: "ascetic", pos: "adjective; also noun", pron: "uh-SET-ik", def: "Practicing strict self-denial and avoiding pleasure; a person who lives this way.", ex: "He lived an ascetic life, owning only a few books and two shirts.", syn: ["austere", "self-denying", "spartan"], ant: ["indulgent", "hedonistic"] },
  { n: 20, word: "assumption", pos: "noun", pron: "uh-SUMP-shun", def: "Something accepted as true without proof.", ex: "The plan rested on the assumption that the weather would cooperate.", syn: ["presumption", "supposition", "premise"], ant: ["proof", "certainty"] },
  { n: 21, word: "astute", pos: "adjective", pron: "uh-STOOT", def: "Having sharp judgment; quick to notice and understand.", ex: "An astute reader will spot the clue in the very first chapter.", syn: ["shrewd", "perceptive", "sharp"], ant: ["obtuse", "naive"] },
  { n: 22, word: "austere", pos: "adjective", pron: "aw-STEER", def: "Severe or strict in manner; plain and without luxury or decoration.", ex: "The headmaster's office was austere: a desk, a chair, and nothing on the walls.", syn: ["stern", "spartan", "stark"], ant: ["lavish", "ornate"] },
  { n: 23, word: "autonomous", pos: "adjective", pron: "aw-TON-uh-mus", def: "Self-governing; acting independently.", ex: "The company is testing autonomous delivery robots on campus.", syn: ["independent", "self-governing", "sovereign"], ant: ["dependent", "controlled"], root: "auto- = self; nom- = law, rule" },
  { n: 24, word: "banal", pos: "adjective", pron: "buh-NAL", def: "So lacking in originality as to be boring.", ex: "The movie's dialogue was so banal that I could predict every line.", syn: ["trite", "clichéd", "unoriginal"], ant: ["original", "fresh"] },
  { n: 25, word: "belie", pos: "verb", pron: "bih-LY", def: "To give a false impression of; to contradict.", ex: "Her calm voice belied how nervous she really was.", syn: ["contradict", "disguise", "misrepresent"], ant: ["reveal", "confirm"] },
  { n: 26, word: "benign", pos: "adjective", pron: "bih-NYN", def: "Gentle and kind; not harmful.", ex: "Luckily, the doctor said the growth was benign.", syn: ["harmless", "kindly", "gentle"], ant: ["malignant", "harmful"], root: "ben- = good" },
  { n: 27, word: "brevity", pos: "noun", pron: "BREV-ih-tee", def: "Shortness of time or concise use of words.", ex: "The brevity of her speech surprised everyone; it lasted only a minute.", syn: ["conciseness", "shortness", "succinctness"], ant: ["verbosity", "length"], root: "brev- = short" },
  { n: 28, word: "buttress", pos: "verb; also noun", pron: "BUH-tris", def: "To support or strengthen; a structure that supports a wall.", ex: "She buttressed her essay with quotes from three historians.", syn: ["support", "reinforce", "bolster"], ant: ["undermine", "weaken"] },
  { n: 29, word: "capricious", pos: "adjective", pron: "kuh-PRISH-us", def: "Given to sudden, unpredictable changes of mood or behavior.", ex: "Spring weather here is capricious: sun at noon, hail by three.", syn: ["fickle", "unpredictable", "erratic"], ant: ["steady", "consistent"] },
  { n: 30, word: "censure", pos: "verb; also noun", pron: "SEN-shur", def: "To express strong formal disapproval; harsh official criticism.", ex: "The Senate voted to censure the member for misusing funds.", syn: ["condemn", "criticize", "rebuke"], ant: ["praise", "commend"] },
  { n: 31, word: "coercion", pos: "noun", pron: "koh-UR-zhun", def: "The use of force or threats to make someone do something.", ex: "He claimed his confession was obtained through coercion.", syn: ["force", "pressure", "intimidation"], ant: ["persuasion", "free will"] },
  { n: 32, word: "colloquial", pos: "adjective", pron: "kuh-LOH-kwee-ul", def: "Used in ordinary or casual conversation; informal.", ex: "\"Gonna\" is colloquial and doesn't belong in a formal essay.", syn: ["informal", "conversational", "casual"], ant: ["formal", "literary"], root: "loqu- = talk" },
  { n: 33, word: "compliance", pos: "noun", pron: "kum-PLY-unce", def: "The act of obeying a rule, order, or request.", ex: "The restaurant was fined for not being in compliance with health codes.", syn: ["obedience", "conformity", "adherence"], ant: ["defiance", "violation"] },
  { n: 34, word: "conciliatory", pos: "adjective", pron: "kun-SIL-ee-uh-tor-ee", def: "Intended to make peace or win someone over.", ex: "After the argument, he sent a conciliatory text with a pizza emoji.", syn: ["peacemaking", "placating", "appeasing"], ant: ["hostile", "antagonistic"] },
  { n: 35, word: "concise", pos: "adjective", pron: "kun-SYCE", def: "Giving a lot of information clearly in few words.", ex: "Keep your answer concise; the judges only have thirty seconds.", syn: ["brief", "succinct", "terse"], ant: ["wordy", "verbose"] },
  { n: 36, word: "condone", pos: "verb", pron: "kun-DOHN", def: "To accept or allow behavior that is considered wrong.", ex: "The school does not condone cheating of any kind.", syn: ["excuse", "overlook", "tolerate"], ant: ["condemn", "forbid"] },
  { n: 37, word: "constraint", pos: "noun", pron: "kun-STRAYNT", def: "A limitation or restriction.", ex: "Budget constraints forced the team to cancel the trip.", syn: ["restriction", "limitation", "restraint"], ant: ["freedom", "liberty"] },
  { n: 38, word: "contentious", pos: "adjective", pron: "kun-TEN-shus", def: "Causing or likely to cause an argument; quarrelsome.", ex: "Whether to ban phones in class was a contentious issue at the meeting.", syn: ["controversial", "argumentative", "disputed"], ant: ["agreeable", "uncontroversial"] },
  { n: 39, word: "corroborate", pos: "verb", pron: "kuh-ROB-uh-rayt", def: "To confirm or give support to a statement or theory.", ex: "Security footage corroborated the shopkeeper's story.", syn: ["confirm", "verify", "substantiate"], ant: ["contradict", "refute"] },
  { n: 40, word: "credulity", pos: "noun", pron: "kruh-DOO-lih-tee", def: "A tendency to believe things too readily.", ex: "The scam relied on the credulity of people who trusted official-looking emails.", syn: ["gullibility", "naivety", "trustfulness"], ant: ["skepticism", "doubt"], root: "cred- = belief" },
  { n: 41, word: "criterion", pos: "noun (pl. criteria)", pron: "kry-TEER-ee-un", def: "A standard by which something is judged.", ex: "Originality was the main criterion for the art prize.", syn: ["standard", "measure", "benchmark"], ant: [] },
  { n: 42, word: "cryptic", pos: "adjective", pron: "KRIP-tik", def: "Having a hidden or mysterious meaning.", ex: "The treasure map included a cryptic riddle instead of directions.", syn: ["mysterious", "puzzling", "enigmatic"], ant: ["clear", "obvious"] },
  { n: 43, word: "cursory", pos: "adjective", pron: "KUR-suh-ree", def: "Hasty and therefore not thorough.", ex: "A cursory look at the contract missed the hidden fees.", syn: ["hasty", "superficial", "perfunctory"], ant: ["thorough", "careful"], root: "cur- = run (running over it quickly)" },
  { n: 44, word: "debilitate", pos: "verb", pron: "dih-BIL-ih-tayt", def: "To make someone or something very weak.", ex: "The flu debilitated him for nearly two weeks.", syn: ["weaken", "incapacitate", "exhaust"], ant: ["strengthen", "invigorate"] },
  { n: 45, word: "debunk", pos: "verb", pron: "dee-BUNK", def: "To expose the falseness of an idea or belief.", ex: "The science teacher debunked the myth that we use only ten percent of our brains.", syn: ["disprove", "refute", "expose"], ant: ["confirm", "prove"] },
  { n: 46, word: "decorum", pos: "noun", pron: "dih-KOR-um", def: "Behavior in keeping with good taste and propriety.", ex: "The judge reminded the crowd to maintain decorum in the courtroom.", syn: ["propriety", "etiquette", "dignity"], ant: ["impropriety", "rudeness"] },
  { n: 47, word: "delineate", pos: "verb", pron: "dih-LIN-ee-ayt", def: "To describe or outline something precisely.", ex: "The syllabus delineates exactly how each assignment will be graded.", syn: ["outline", "define", "describe"], ant: ["obscure", "blur"] },
  { n: 48, word: "deprecate", pos: "verb", pron: "DEP-rih-kayt", def: "To express disapproval of; to play down or belittle.", ex: "She tends to deprecate her own achievements when people praise her.", syn: ["disapprove", "belittle", "criticize"], ant: ["approve", "praise"] },
  { n: 49, word: "derision", pos: "noun", pron: "dih-RIZH-un", def: "Contemptuous ridicule or mockery.", ex: "His idea was met with derision at first, but later it made millions.", syn: ["mockery", "ridicule", "scorn"], ant: ["respect", "admiration"] },
  { n: 50, word: "derivative", pos: "adjective", pron: "dih-RIV-uh-tiv", def: "Copied or adapted from others; not original.", ex: "Critics called the sequel derivative, saying it just recycled the first film.", syn: ["unoriginal", "imitative", "copied"], ant: ["original", "innovative"] },
  { n: 51, word: "detachment", pos: "noun", pron: "dih-TACH-munt", def: "Emotional distance; lack of involvement.", ex: "The surgeon spoke about the risks with calm detachment.", syn: ["aloofness", "indifference", "objectivity"], ant: ["involvement", "concern"] },
  { n: 52, word: "digression", pos: "noun", pron: "dy-GRESH-un", def: "A temporary departure from the main subject.", ex: "After a long digression about his cat, the professor returned to the lecture.", syn: ["tangent", "detour", "aside"], ant: [] },
  { n: 53, word: "discerning", pos: "adjective", pron: "dih-SUR-ning", def: "Having or showing good judgment and taste.", ex: "Discerning shoppers check the ingredients before buying.", syn: ["perceptive", "astute", "judicious"], ant: ["undiscriminating", "obtuse"] },
  { n: 54, word: "discrepancy", pos: "noun", pron: "dih-SKREP-un-see", def: "A lack of agreement between facts that should match.", ex: "The accountant found a discrepancy between the receipts and the bank records.", syn: ["inconsistency", "mismatch", "difference"], ant: ["agreement", "consistency"] },
  { n: 55, word: "disdain", pos: "verb; also noun", pron: "dis-DAYN", def: "To regard as unworthy; a feeling of contempt.", ex: "The food critic looked at the soggy fries with obvious disdain.", syn: ["contempt", "scorn", "despise"], ant: ["respect", "admire"] },
  { n: 56, word: "dismiss", pos: "verb", pron: "dis-MISS", def: "To reject as unworthy of consideration; to send away.", ex: "The coach dismissed the rumors that he was leaving.", syn: ["reject", "disregard", "discount"], ant: ["consider", "accept"] },
  { n: 57, word: "disparage", pos: "verb", pron: "dih-SPAIR-ij", def: "To speak of as unimportant or of little worth.", ex: "Good leaders don't disparage their rivals; they focus on their own plans.", syn: ["belittle", "denigrate", "run down"], ant: ["praise", "compliment"] },
  { n: 58, word: "disparity", pos: "noun", pron: "dih-SPAIR-ih-tee", def: "A great difference, especially an unfair one.", ex: "The report revealed a disparity in funding between city and rural schools.", syn: ["inequality", "gap", "imbalance"], ant: ["equality", "parity"], root: "dis- = not; par- = equal" },
  { n: 59, word: "disseminate", pos: "verb", pron: "dih-SEM-ih-nayt", def: "To spread information widely.", ex: "Health officials used social media to disseminate safety tips.", syn: ["spread", "circulate", "distribute"], ant: ["suppress", "withhold"], root: "dis- = apart; semin- = seed (scattering seeds)" },
  { n: 60, word: "divergent", pos: "adjective", pron: "dy-VUR-junt", def: "Moving or extending in different directions; differing.", ex: "The twins have divergent tastes: one loves horror, the other romance.", syn: ["differing", "contrasting", "dissimilar"], ant: ["convergent", "similar"] },
  { n: 61, word: "document", pos: "verb; also noun", pron: "DOK-yuh-ment", def: "To record in detail; a written or official record.", ex: "The scientist documented every step of the experiment.", syn: ["record", "chronicle", "log"], ant: [] },
  { n: 62, word: "dogmatic", pos: "adjective", pron: "dawg-MAT-ik", def: "Insisting that one's beliefs are true without considering other views.", ex: "His dogmatic attitude made it impossible to have a real debate.", syn: ["opinionated", "rigid", "doctrinaire"], ant: ["open-minded", "flexible"] },
  { n: 63, word: "eclectic", pos: "adjective", pron: "ih-KLEK-tik", def: "Drawing from a wide range of sources or styles.", ex: "The café's eclectic menu offers tacos, ramen, and Greek salads.", syn: ["diverse", "varied", "wide-ranging"], ant: ["uniform", "narrow"] },
  { n: 64, word: "elucidate", pos: "verb", pron: "ih-LOO-sih-dayt", def: "To make something clear; to explain.", ex: "The diagram helped elucidate how the engine works.", syn: ["clarify", "explain", "illuminate"], ant: ["confuse", "obscure"], root: "luc- = light (shedding light)" },
  { n: 65, word: "elusive", pos: "adjective", pron: "ih-LOO-siv", def: "Difficult to find, catch, or achieve.", ex: "A perfect score remained elusive despite months of practice.", syn: ["evasive", "slippery", "hard to pin down"], ant: ["attainable", "accessible"] },
  { n: 66, word: "embellish", pos: "verb", pron: "em-BEL-ish", def: "To make more attractive by adding details; to exaggerate a story.", ex: "Every time he tells the fishing story, he embellishes it a little more.", syn: ["decorate", "adorn", "exaggerate"], ant: ["simplify", "understate"] },
  { n: 67, word: "emulate", pos: "verb", pron: "EM-yuh-layt", def: "To match or surpass, usually by imitation.", ex: "Young players often emulate the moves of their favorite athletes.", syn: ["imitate", "copy", "follow"], ant: [] },
  { n: 68, word: "endorse", pos: "verb", pron: "en-DORS", def: "To declare public approval or support.", ex: "Three former mayors endorsed her campaign.", syn: ["support", "back", "approve"], ant: ["oppose", "reject"] },
  { n: 69, word: "enhance", pos: "verb", pron: "en-HANCE", def: "To improve the quality, value, or extent of something.", ex: "A pinch of salt can enhance the sweetness of chocolate.", syn: ["improve", "boost", "heighten"], ant: ["diminish", "reduce"] },
  { n: 70, word: "ephemeral", pos: "adjective", pron: "ih-FEM-ur-ul", def: "Lasting for a very short time.", ex: "Snapchat messages are designed to be ephemeral.", syn: ["fleeting", "transient", "short-lived"], ant: ["permanent", "lasting"] },
  { n: 71, word: "equivocal", pos: "adjective", pron: "ih-KWIV-uh-kul", def: "Open to more than one interpretation; deliberately vague.", ex: "When asked about the rumors, the senator gave an equivocal reply.", syn: ["ambiguous", "vague", "noncommittal"], ant: ["clear", "unequivocal"], root: "equ- = equal; voc- = voice (speaking two ways equally)" },
  { n: 72, word: "erudite", pos: "adjective", pron: "AIR-yuh-dyt", def: "Having or showing great knowledge from study.", ex: "The erudite professor could quote Shakespeare from memory.", syn: ["learned", "scholarly", "knowledgeable"], ant: ["ignorant", "uneducated"] },
  { n: 73, word: "esoteric", pos: "adjective", pron: "es-uh-TAIR-ik", def: "Understood by only a small group with special knowledge.", ex: "The podcast covers esoteric topics like medieval sword-making.", syn: ["obscure", "arcane", "specialized"], ant: ["well-known", "familiar"] },
  { n: 74, word: "eulogy", pos: "noun", pron: "YOO-luh-jee", def: "A speech or writing that praises someone, especially at a funeral.", ex: "Her brother delivered a heartfelt eulogy at the service.", syn: ["tribute", "praise", "homage"], ant: ["criticism", "condemnation"], root: "eu- = good; log- = word" },
  { n: 75, word: "exacerbate", pos: "verb", pron: "ig-ZAS-ur-bayt", def: "To make a problem or bad situation worse.", ex: "Scratching a bug bite only exacerbates the itch.", syn: ["worsen", "aggravate", "intensify"], ant: ["alleviate", "relieve"], root: "acerb- = bitter" },
  { n: 76, word: "exemplary", pos: "adjective", pron: "ig-ZEM-pluh-ree", def: "Serving as a desirable model; excellent.", ex: "The volunteer was honored for her exemplary service.", syn: ["model", "ideal", "outstanding"], ant: ["deplorable", "poor"] },
  { n: 77, word: "expedient", pos: "adjective; also noun", pron: "ik-SPEE-dee-unt", def: "Convenient and practical, though possibly improper; a means to an end.", ex: "Skipping the safety check was expedient but dangerous.", syn: ["convenient", "practical", "advantageous"], ant: ["inexpedient", "impractical"] },
  { n: 78, word: "explicit", pos: "adjective", pron: "ik-SPLIS-it", def: "Stated clearly and in detail, leaving no room for confusion.", ex: "The sign gave explicit directions: no bikes beyond this point.", syn: ["clear", "direct", "specific"], ant: ["implicit", "vague"] },
  { n: 79, word: "extol", pos: "verb", pron: "ik-STOHL", def: "To praise enthusiastically.", ex: "The review extolled the restaurant's handmade pasta.", syn: ["praise", "laud", "glorify"], ant: ["criticize", "belittle"] },
  { n: 80, word: "extraneous", pos: "adjective", pron: "ik-STRAY-nee-us", def: "Irrelevant or unrelated to the subject at hand.", ex: "Cut the extraneous details so your main point stands out.", syn: ["irrelevant", "unnecessary", "superfluous"], ant: ["relevant", "essential"], root: "extra- = outside, beyond" },
  { n: 81, word: "extricate", pos: "verb", pron: "EK-strih-kayt", def: "To free from a difficult situation or tangle.", ex: "Firefighters worked for an hour to extricate the driver from the car.", syn: ["free", "release", "disentangle"], ant: ["entangle", "trap"] },
  { n: 82, word: "exuberance", pos: "noun", pron: "ig-ZOO-bur-unce", def: "The quality of being full of energy, excitement, and cheerfulness.", ex: "The puppy greeted us with total exuberance.", syn: ["enthusiasm", "liveliness", "zest"], ant: ["apathy", "gloom"] },
  { n: 83, word: "fallacious", pos: "adjective", pron: "fuh-LAY-shus", def: "Based on a mistaken belief or faulty reasoning.", ex: "The ad's claim that \"everyone is buying it\" is a fallacious argument.", syn: ["false", "erroneous", "flawed"], ant: ["valid", "sound"] },
  { n: 84, word: "fastidious", pos: "adjective", pron: "fa-STID-ee-us", def: "Very attentive to detail and accuracy; hard to please.", ex: "He is so fastidious that he irons his socks.", syn: ["meticulous", "fussy", "particular"], ant: ["careless", "sloppy"] },
  { n: 85, word: "feasible", pos: "adjective", pron: "FEE-zuh-bul", def: "Possible to do easily or practically.", ex: "Building the treehouse in one weekend turned out not to be feasible.", syn: ["practicable", "viable", "achievable"], ant: ["impossible", "impractical"] },
  { n: 86, word: "fervor", pos: "noun", pron: "FUR-vur", def: "Intense and passionate feeling.", ex: "The fans cheered with such fervor that the stadium shook.", syn: ["passion", "zeal", "intensity"], ant: ["apathy", "indifference"] },
  { n: 87, word: "flagrant", pos: "adjective", pron: "FLAY-grunt", def: "Conspicuously and shockingly wrong or offensive.", ex: "The referee called a flagrant foul after the player shoved his opponent.", syn: ["blatant", "glaring", "outrageous"], ant: ["subtle", "minor"] },
  { n: 88, word: "frivolous", pos: "adjective", pron: "FRIV-uh-lus", def: "Not having any serious purpose or value; silly.", ex: "She spent her birthday money on frivolous things like glitter stickers.", syn: ["trivial", "silly", "petty"], ant: ["serious", "important"] },
  { n: 89, word: "furtive", pos: "adjective", pron: "FUR-tiv", def: "Attempting to avoid notice; secretive.", ex: "He cast a furtive glance at the answer key on the teacher's desk.", syn: ["sneaky", "stealthy", "secretive"], ant: ["open", "brazen"], root: "fur- = thief" },
  { n: 90, word: "garrulous", pos: "adjective", pron: "GAIR-uh-lus", def: "Excessively talkative, especially about trivial things.", ex: "My garrulous seatmate talked for the entire six-hour flight.", syn: ["talkative", "chatty", "loquacious"], ant: ["taciturn", "reticent"] },
  { n: 91, word: "gravity", pos: "noun", pron: "GRAV-ih-tee", def: "Extreme importance or seriousness.", ex: "The doctor's tone made us realize the gravity of the situation.", syn: ["seriousness", "importance", "solemnity"], ant: ["levity", "triviality"], root: "grav- = heavy" },
  { n: 92, word: "gregarious", pos: "adjective", pron: "grih-GAIR-ee-us", def: "Fond of company; sociable; living in groups.", ex: "Gregarious by nature, she knew everyone at the party within an hour.", syn: ["sociable", "outgoing", "friendly"], ant: ["introverted", "reclusive"], root: "greg- = flock, herd" },
  { n: 93, word: "guile", pos: "noun", pron: "GYLE", def: "Sly or cunning intelligence used to deceive.", ex: "The fox in the fable used guile to trick the crow.", syn: ["cunning", "craftiness", "deceit"], ant: ["honesty", "candor"] },
  { n: 94, word: "haughtiness", pos: "noun", pron: "HAW-tee-nis", def: "Arrogant superiority and disdain for others.", ex: "Her haughtiness made her unpopular with the rest of the team.", syn: ["arrogance", "pride", "conceit"], ant: ["humility", "modesty"] },
  { n: 95, word: "heresy", pos: "noun", pron: "HAIR-uh-see", def: "A belief or opinion strongly opposed to accepted doctrine.", ex: "In our house, saying you don't like pizza is practically heresy.", syn: ["dissent", "unorthodoxy", "blasphemy"], ant: ["orthodoxy", "conformity"] },
  { n: 96, word: "hierarchy", pos: "noun", pron: "HY-ur-ar-kee", def: "A system in which people or things are ranked one above another.", ex: "In the wolf pack's hierarchy, the alpha eats first.", syn: ["ranking", "pecking order", "chain of command"], ant: ["equality"] },
  { n: 97, word: "homogeneous", pos: "adjective", pron: "hoh-muh-JEE-nee-us", def: "Of the same kind; alike throughout.", ex: "Stir the batter until it is completely homogeneous.", syn: ["uniform", "alike", "consistent"], ant: ["heterogeneous", "diverse"], root: "homo- = same; gen- = kind" },
  { n: 98, word: "hyperbole", pos: "noun", pron: "hy-PUR-buh-lee", def: "Exaggerated statements not meant to be taken literally.", ex: "\"I've told you a million times\" is a classic hyperbole.", syn: ["exaggeration", "overstatement", "embellishment"], ant: ["understatement"], root: "hyper- = above, excessively" },
  { n: 99, word: "hypothetical", pos: "adjective", pron: "hy-puh-THET-ih-kul", def: "Based on a suggested idea rather than known facts; imagined.", ex: "Let's consider a hypothetical: what if school started at 10 a.m.?", syn: ["theoretical", "supposed", "speculative"], ant: ["actual", "real"] },
  { n: 100, word: "immutable", pos: "adjective", pron: "ih-MYOO-tuh-bul", def: "Unchanging over time; unable to be changed.", ex: "The laws of physics are immutable, no matter how late you are.", syn: ["unchangeable", "fixed", "permanent"], ant: ["changeable", "variable"], root: "im- = not; mut- = change" },
  { n: 102, word: "impeccable", pos: "adjective", pron: "im-PEK-uh-bul", def: "In accordance with the highest standards; flawless.", ex: "Her impeccable manners impressed the interviewer.", syn: ["flawless", "perfect", "faultless"], ant: ["flawed", "imperfect"] },
  { n: 103, word: "impede", pos: "verb", pron: "im-PEED", def: "To delay or block the progress of.", ex: "Fallen trees impeded the ambulance's route.", syn: ["hinder", "obstruct", "hamper"], ant: ["assist", "facilitate"], root: "ped- = foot (something tangling your feet)" },
  { n: 104, word: "implement", pos: "verb; also noun", pron: "IM-pluh-ment", def: "To put a plan into effect; a tool.", ex: "The school will implement the new lunch schedule next month.", syn: ["execute", "carry out", "apply"], ant: ["abandon", "neglect"] },
  { n: 105, word: "inadvertently", pos: "adverb", pron: "in-ud-VUR-tunt-lee", def: "Without intention; accidentally.", ex: "I inadvertently hit \"reply all\" on the embarrassing email.", syn: ["accidentally", "unintentionally", "by mistake"], ant: ["deliberately", "intentionally"] },
  { n: 106, word: "inane", pos: "adjective", pron: "ih-NAYN", def: "Silly; lacking sense or meaning.", ex: "The reality show was full of inane arguments about nothing.", syn: ["silly", "senseless", "pointless"], ant: ["sensible", "meaningful"] },
  { n: 107, word: "incite", pos: "verb", pron: "in-SYTE", def: "To encourage or stir up violent or unlawful behavior.", ex: "The post was removed for trying to incite violence.", syn: ["provoke", "instigate", "stir up"], ant: ["calm", "discourage"] },
  { n: 108, word: "incongruous", pos: "adjective", pron: "in-KONG-groo-us", def: "Not in harmony with the surroundings; out of place.", ex: "A tuxedo looked incongruous at the beach barbecue.", syn: ["out of place", "inappropriate", "jarring"], ant: ["fitting", "harmonious"] },
  { n: 109, word: "incorrigible", pos: "adjective", pron: "in-KOR-ih-juh-bul", def: "Not able to be corrected or reformed.", ex: "My incorrigible little brother keeps hiding my shoes no matter how often he's caught.", syn: ["incurable", "hopeless", "unreformable"], ant: ["reformable", "manageable"] },
  { n: 110, word: "indifferent", pos: "adjective", pron: "in-DIF-ur-unt", def: "Having no interest or concern; unconcerned.", ex: "The cat seemed totally indifferent to its expensive new toy.", syn: ["apathetic", "unconcerned", "detached"], ant: ["interested", "concerned"] },
  { n: 111, word: "induce", pos: "verb", pron: "in-DOOS", def: "To persuade or bring about; to cause.", ex: "Nothing could induce him to try the spicy noodles again.", syn: ["persuade", "prompt", "cause"], ant: ["prevent", "discourage"] },
  { n: 112, word: "inherent", pos: "adjective", pron: "in-HEER-unt", def: "Existing as a permanent, essential part of something.", ex: "Skydiving has risks that are inherent to the sport.", syn: ["intrinsic", "built-in", "essential"], ant: ["extrinsic", "acquired"] },
  { n: 113, word: "innate", pos: "adjective", pron: "ih-NAYT", def: "Present from birth; natural rather than learned.", ex: "Babies have an innate ability to recognize faces.", syn: ["inborn", "natural", "inherent"], ant: ["learned", "acquired"], root: "nat- = born" },
  { n: 114, word: "innocuous", pos: "adjective", pron: "ih-NOK-yoo-us", def: "Not harmful or offensive.", ex: "What seemed like an innocuous question started a huge argument.", syn: ["harmless", "inoffensive", "safe"], ant: ["harmful", "offensive"] },
  { n: 115, word: "insipid", pos: "adjective", pron: "in-SIP-id", def: "Lacking flavor, interest, or excitement.", ex: "The hospital soup was insipid, so I added pepper.", syn: ["bland", "tasteless", "dull"], ant: ["flavorful", "exciting"] },
  { n: 116, word: "instigate", pos: "verb", pron: "IN-stih-gayt", def: "To bring about or start an action or event.", ex: "Investigators wanted to know who instigated the food fight.", syn: ["initiate", "provoke", "incite"], ant: ["stop", "halt"] },
  { n: 117, word: "intrepid", pos: "adjective", pron: "in-TREP-id", def: "Fearless and adventurous.", ex: "The intrepid explorers crossed the glacier on foot.", syn: ["fearless", "brave", "bold"], ant: ["timid", "cowardly"] },
  { n: 118, word: "ironic", pos: "adjective", pron: "eye-RON-ik", def: "Happening in the opposite way to what is expected; using words to mean the opposite.", ex: "It was ironic that the fire station burned down.", syn: ["paradoxical", "sardonic", "unexpected"], ant: ["literal", "expected"] },
  { n: 119, word: "jocular", pos: "adjective", pron: "JOK-yuh-lur", def: "Fond of joking; humorous and playful.", ex: "His jocular emails always made the office laugh.", syn: ["humorous", "playful", "jokey"], ant: ["serious", "solemn"], root: "Latin jocus = joke" },
  { n: 120, word: "juxtaposition", pos: "noun", pron: "juk-stuh-puh-ZISH-un", def: "Placing two things side by side, often to show contrast.", ex: "The photo's juxtaposition of a tiny kitten and a huge dog made it go viral.", syn: ["contrast", "comparison", "pairing"], ant: ["separation"] },
  { n: 121, word: "laconic", pos: "adjective", pron: "luh-KON-ik", def: "Using very few words.", ex: "Asked how the test went, my laconic friend just said, \"Fine.\"", syn: ["terse", "brief", "succinct"], ant: ["verbose", "garrulous"] },
  { n: 122, word: "lavish", pos: "adjective; also verb", pron: "LAV-ish", def: "Rich, elaborate, or generous; to give generously.", ex: "The wedding was lavish, with fireworks and a ten-tier cake.", syn: ["extravagant", "luxurious", "generous"], ant: ["meager", "frugal"] },
  { n: 123, word: "lethargic", pos: "adjective", pron: "luh-THAR-jik", def: "Sluggish, tired, and lacking energy.", ex: "The heat made everyone lethargic by mid-afternoon.", syn: ["sluggish", "drowsy", "listless"], ant: ["energetic", "lively"] },
  { n: 124, word: "levity", pos: "noun", pron: "LEV-ih-tee", def: "Humor or lack of seriousness, especially when inappropriate.", ex: "A bit of levity helped ease the tension before the big game.", syn: ["humor", "lightheartedness", "frivolity"], ant: ["gravity", "seriousness"], root: "lev- = light (not heavy)" },
  { n: 125, word: "malicious", pos: "adjective", pron: "muh-LISH-us", def: "Intending to do harm.", ex: "Someone spread malicious rumors about the new student.", syn: ["spiteful", "hateful", "vicious"], ant: ["kind", "benevolent"], root: "mal- = bad" },
  { n: 126, word: "metaphor", pos: "noun", pron: "MET-uh-for", def: "A figure of speech that describes something as if it were something else.", ex: "\"Time is a thief\" is a metaphor for how quickly life passes.", syn: ["figure of speech", "symbol", "image"], ant: [] },
  { n: 127, word: "meticulous", pos: "adjective", pron: "muh-TIK-yuh-lus", def: "Showing great attention to detail; very careful.", ex: "The meticulous model builder painted each tiny window by hand.", syn: ["careful", "thorough", "painstaking"], ant: ["careless", "sloppy"] },
  { n: 128, word: "mitigate", pos: "verb", pron: "MIT-ih-gayt", def: "To make less severe or harmful.", ex: "Sea walls help mitigate damage from storm surges.", syn: ["lessen", "reduce", "alleviate"], ant: ["aggravate", "intensify"] },
  { n: 129, word: "mollify", pos: "verb", pron: "MOL-uh-fy", def: "To calm the anger or anxiety of someone.", ex: "The waiter mollified the upset customer with a free dessert.", syn: ["soothe", "pacify", "placate"], ant: ["anger", "provoke"], root: "moll- = soft" },
  { n: 130, word: "mundane", pos: "adjective", pron: "mun-DAYN", def: "Lacking interest or excitement; ordinary.", ex: "Laundry and dishes are mundane, but someone has to do them.", syn: ["ordinary", "routine", "dull"], ant: ["extraordinary", "exciting"] },
  { n: 131, word: "nonchalance", pos: "noun", pron: "non-shuh-LAHNCE", def: "A relaxed, calm manner that shows a lack of concern.", ex: "He hit the winning shot and walked off with total nonchalance.", syn: ["composure", "indifference", "coolness"], ant: ["anxiety", "concern"] },
  { n: 132, word: "notoriety", pos: "noun", pron: "noh-tuh-RY-ih-tee", def: "Fame for something bad.", ex: "The hacker gained notoriety after breaking into a government website.", syn: ["infamy", "disrepute", "ill fame"], ant: ["obscurity", "good reputation"] },
  { n: 133, word: "nurture", pos: "verb; also noun", pron: "NUR-chur", def: "To care for and encourage growth or development.", ex: "Great teachers nurture curiosity in their students.", syn: ["foster", "cultivate", "raise"], ant: ["neglect", "abandon"] },
  { n: 134, word: "obdurate", pos: "adjective", pron: "OB-dur-it", def: "Stubbornly refusing to change one's opinion.", ex: "Despite all the evidence, he remained obdurate.", syn: ["stubborn", "unyielding", "inflexible"], ant: ["flexible", "yielding"], root: "dur- = hard" },
  { n: 135, word: "oblivion", pos: "noun", pron: "uh-BLIV-ee-un", def: "The state of being unaware or forgotten.", ex: "Once-famous bands can fade into oblivion within a few years.", syn: ["obscurity", "unawareness", "nothingness"], ant: ["awareness", "fame"] },
  { n: 136, word: "opportunist", pos: "noun", pron: "op-ur-TOO-nist", def: "A person who takes advantage of situations, often without regard to principles.", ex: "The opportunist raised prices on water bottles right after the storm.", syn: ["exploiter", "self-seeker", "chancer"], ant: [] },
  { n: 137, word: "opulence", pos: "noun", pron: "OP-yuh-lunce", def: "Great wealth or luxuriousness.", ex: "The palace's opulence included gold doorknobs and crystal chandeliers.", syn: ["luxury", "wealth", "splendor"], ant: ["poverty", "austerity"] },
  { n: 138, word: "ostentatious", pos: "adjective", pron: "os-ten-TAY-shus", def: "Designed to impress or attract notice; showy.", ex: "He drove an ostentatious gold sports car to the reunion.", syn: ["showy", "flashy", "pretentious"], ant: ["modest", "understated"] },
  { n: 139, word: "partisan", pos: "adjective; also noun", pron: "PAR-tih-zun", def: "Strongly supporting one party or cause; a strong supporter.", ex: "The debate turned partisan, with each side refusing to compromise.", syn: ["biased", "one-sided", "factional"], ant: ["nonpartisan", "impartial"] },
  { n: 140, word: "pathos", pos: "noun", pron: "PAY-thos", def: "A quality that evokes pity or sadness.", ex: "The film's final scene was full of pathos, leaving the audience in tears.", syn: ["poignancy", "sadness", "emotion"], ant: [], root: "path- = feeling" },
  { n: 141, word: "peripheral", pos: "adjective", pron: "puh-RIF-ur-ul", def: "On the edge or outskirts; of minor importance.", ex: "I saw the ball out of my peripheral vision just in time.", syn: ["outer", "secondary", "marginal"], ant: ["central", "core"], root: "peri- = around" },
  { n: 142, word: "pervasive", pos: "adjective", pron: "pur-VAY-siv", def: "Spreading widely through an area or group.", ex: "Smartphones have had a pervasive effect on how teens communicate.", syn: ["widespread", "prevalent", "ubiquitous"], ant: ["limited", "rare"] },
  { n: 143, word: "placate", pos: "verb", pron: "PLAY-kayt", def: "To make someone less angry or hostile.", ex: "The manager tried to placate the customers with free coffee.", syn: ["appease", "pacify", "mollify"], ant: ["provoke", "enrage"] },
  { n: 144, word: "pragmatic", pos: "adjective", pron: "prag-MAT-ik", def: "Dealing with things sensibly and realistically.", ex: "Instead of a dream car, she made the pragmatic choice of a used hatchback.", syn: ["practical", "realistic", "sensible"], ant: ["idealistic", "impractical"] },
  { n: 145, word: "preclude", pos: "verb", pron: "prih-KLOOD", def: "To prevent from happening; make impossible.", ex: "A sprained ankle precluded her from running in the race.", syn: ["prevent", "rule out", "prohibit"], ant: ["allow", "enable"] },
  { n: 146, word: "predilection", pos: "noun", pron: "pred-ih-LEK-shun", def: "A preference or special liking for something.", ex: "My dog has a predilection for chewing on left shoes.", syn: ["preference", "fondness", "liking"], ant: ["dislike", "aversion"] },
  { n: 147, word: "presumptuous", pos: "adjective", pron: "prih-ZUMP-choo-us", def: "Overconfident; taking liberties one has no right to.", ex: "It was presumptuous of him to plan the party at my house without asking.", syn: ["arrogant", "forward", "overconfident"], ant: ["modest", "humble"] },
  { n: 148, word: "prevalent", pos: "adjective", pron: "PREV-uh-lunt", def: "Widespread in a particular area or time.", ex: "Allergies are especially prevalent in the spring.", syn: ["common", "widespread", "pervasive"], ant: ["rare", "uncommon"] },
  { n: 149, word: "prodigal", pos: "adjective; also noun", pron: "PROD-ih-gul", def: "Spending money or resources wastefully; a person who does this.", ex: "His prodigal spending left him broke by the end of the month.", syn: ["wasteful", "extravagant", "spendthrift"], ant: ["thrifty", "frugal"] },
  { n: 150, word: "profane", pos: "verb; also adjective", pron: "pruh-FAYN", def: "To treat something sacred with disrespect; irreverent or vulgar.", ex: "Vandals profaned the cemetery by spray-painting the headstones.", syn: ["desecrate", "defile", "irreverent"], ant: ["sacred", "revere"] },
  { n: 151, word: "proliferation", pos: "noun", pron: "pruh-lif-uh-RAY-shun", def: "Rapid increase in number or spread.", ex: "The proliferation of food delivery apps changed how cities eat.", syn: ["spread", "multiplication", "expansion"], ant: ["decline", "decrease"] },
  { n: 152, word: "prolific", pos: "adjective", pron: "pruh-LIF-ik", def: "Producing a great deal of something.", ex: "The prolific author published three novels in a single year.", syn: ["productive", "fruitful", "abundant"], ant: ["unproductive", "barren"] },
  { n: 153, word: "proximity", pos: "noun", pron: "prok-SIM-ih-tee", def: "Nearness in space, time, or relationship.", ex: "The apartment's proximity to the subway made it worth the price.", syn: ["nearness", "closeness", "vicinity"], ant: ["distance", "remoteness"] },
  { n: 154, word: "prudent", pos: "adjective", pron: "PROO-dunt", def: "Acting with care and thought for the future.", ex: "It's prudent to back up your files before updating your computer.", syn: ["wise", "sensible", "careful"], ant: ["reckless", "rash"] },
  { n: 155, word: "quandary", pos: "noun", pron: "KWON-dree", def: "A state of uncertainty over what to do in a difficult situation.", ex: "Invited to two parties on the same night, she was in a quandary.", syn: ["dilemma", "predicament", "puzzle"], ant: ["certainty", "solution"] },
  { n: 156, word: "rancor", pos: "noun", pron: "RANG-kur", def: "Long-lasting bitterness or resentment.", ex: "Years after the breakup, he still felt rancor toward his old bandmates.", syn: ["bitterness", "resentment", "hostility"], ant: ["goodwill", "friendliness"] },
  { n: 157, word: "rebuttal", pos: "noun", pron: "rih-BUT-ul", def: "An argument or evidence that contradicts a claim.", ex: "The debate team prepared a sharp rebuttal to every point.", syn: ["refutation", "counterargument", "denial"], ant: ["agreement", "confirmation"] },
  { n: 158, word: "recluse", pos: "noun", pron: "REK-loos", def: "A person who lives alone and avoids other people.", ex: "The famous writer became a recluse, rarely leaving his cabin.", syn: ["hermit", "loner", "solitary"], ant: ["socialite", "extrovert"] },
  { n: 159, word: "recount", pos: "verb", pron: "rih-KOUNT", def: "To tell someone about an event; to narrate.", ex: "She recounted her adventures backpacking through Peru.", syn: ["narrate", "describe", "relate"], ant: [] },
  { n: 160, word: "rectify", pos: "verb", pron: "REK-tih-fy", def: "To put something right; to correct.", ex: "The company promised to rectify the billing mistake within a week.", syn: ["correct", "fix", "remedy"], ant: ["worsen", "damage"], root: "rect- = right, straight" },
  { n: 161, word: "redundant", pos: "adjective", pron: "rih-DUN-dunt", def: "No longer needed; unnecessarily repetitive.", ex: "\"Free gift\" is redundant, since all gifts are free.", syn: ["unnecessary", "superfluous", "repetitive"], ant: ["necessary", "essential"] },
  { n: 162, word: "refute", pos: "verb", pron: "rih-FYOOT", def: "To prove a statement or argument to be wrong.", ex: "The scientist refuted the claim with data from ten studies.", syn: ["disprove", "rebut", "debunk"], ant: ["confirm", "prove"], note: "Refute means to prove wrong, which is stronger than just arguing against (rebut)." },
  { n: 163, word: "relegate", pos: "verb", pron: "REL-ih-gayt", def: "To assign to a lower or less important position.", ex: "After the injury, he was relegated to the bench.", syn: ["demote", "downgrade", "banish"], ant: ["promote", "elevate"] },
  { n: 164, word: "renounce", pos: "verb", pron: "rih-NOUNCE", def: "To formally give up a claim, right, or belief.", ex: "The prince renounced his title to marry the woman he loved.", syn: ["give up", "abandon", "reject"], ant: ["claim", "embrace"] },
  { n: 165, word: "reprimand", pos: "noun; also verb", pron: "REP-ruh-mand", def: "A formal expression of disapproval; to scold formally.", ex: "She received a written reprimand for being late five times.", syn: ["rebuke", "scolding", "admonish"], ant: ["praise", "commend"] },
  { n: 166, word: "reprove", pos: "verb", pron: "rih-PROOV", def: "To scold or correct, usually gently.", ex: "The librarian reproved the kids for talking too loudly.", syn: ["scold", "chide", "admonish"], ant: ["praise", "approve"] },
  { n: 167, word: "repudiate", pos: "verb", pron: "rih-PYOO-dee-ayt", def: "To refuse to accept or be associated with; to deny.", ex: "The candidate repudiated the offensive comments made by a supporter.", syn: ["reject", "disown", "deny"], ant: ["accept", "embrace"] },
  { n: 168, word: "reserve", pos: "noun; also verb", pron: "rih-ZURV", def: "A tendency to hold back one's feelings; to keep for later use.", ex: "Despite his usual reserve, he cried at the graduation ceremony.", syn: ["restraint", "reticence", "aloofness"], ant: ["openness", "warmth"] },
  { n: 169, word: "resigned", pos: "adjective", pron: "rih-ZYND", def: "Accepting something unpleasant that cannot be avoided.", ex: "With the flight canceled, we were resigned to spending the night at the airport.", syn: ["accepting", "unresisting", "patient"], ant: ["resistant", "defiant"] },
  { n: 170, word: "resolution", pos: "noun", pron: "rez-uh-LOO-shun", def: "A firm decision to do something; determination.", ex: "Her resolution to run every morning lasted the whole year.", syn: ["determination", "resolve", "commitment"], ant: ["indecision", "hesitation"] },
  { n: 171, word: "reticent", pos: "adjective", pron: "RET-ih-sunt", def: "Not revealing one's thoughts or feelings readily; reserved.", ex: "He was reticent about his past and changed the subject whenever it came up.", syn: ["reserved", "quiet", "restrained"], ant: ["open", "talkative"] },
  { n: 172, word: "retract", pos: "verb", pron: "rih-TRAKT", def: "To take back a statement or offer; to pull back.", ex: "The newspaper retracted the story after learning it was false.", syn: ["withdraw", "take back", "recant"], ant: ["confirm", "maintain"], root: "re- = back; tract- = pull" },
  { n: 173, word: "rhetorical", pos: "adjective", pron: "rih-TOR-ih-kul", def: "Relating to persuasive speech; asked for effect, not for an answer.", ex: "\"Who doesn't love summer?\" was a rhetorical question.", syn: ["oratorical", "persuasive", "stylistic"], ant: [] },
  { n: 174, word: "satirical", pos: "adjective", pron: "suh-TEER-ih-kul", def: "Using humor, irony, or exaggeration to criticize.", ex: "The satirical news site mocks politicians with fake headlines.", syn: ["mocking", "ironic", "sarcastic"], ant: ["serious", "earnest"] },
  { n: 175, word: "scrupulous", pos: "adjective", pron: "SKROO-pyuh-lus", def: "Very careful and thorough; extremely honest.", ex: "The scrupulous cashier returned the extra twenty dollars.", syn: ["honest", "careful", "meticulous"], ant: ["unscrupulous", "careless"] },
  { n: 176, word: "scrutiny", pos: "noun", pron: "SKROO-tih-nee", def: "Close, critical examination.", ex: "Celebrities live under constant public scrutiny.", syn: ["inspection", "examination", "analysis"], ant: ["neglect", "disregard"] },
  { n: 177, word: "skeptic", pos: "noun", pron: "SKEP-tik", def: "A person inclined to question or doubt accepted opinions.", ex: "As a skeptic, she wanted to see the evidence before believing the rumor.", syn: ["doubter", "cynic", "questioner"], ant: ["believer", "devotee"] },
  { n: 178, word: "soporific", pos: "adjective", pron: "sop-uh-RIF-ik", def: "Tending to make one sleepy.", ex: "The rain on the roof had a soporific effect.", syn: ["sleep-inducing", "sedative", "boring"], ant: ["stimulating", "invigorating"] },
  { n: 179, word: "specious", pos: "adjective", pron: "SPEE-shus", def: "Seemingly reasonable but actually wrong.", ex: "The ad made a specious claim that the gum would make you smarter.", syn: ["misleading", "deceptive", "false"], ant: ["valid", "sound"] },
  { n: 180, word: "sporadic", pos: "adjective", pron: "spuh-RAD-ik", def: "Occurring at irregular intervals; scattered.", ex: "The Wi-Fi was sporadic, cutting out every few minutes.", syn: ["occasional", "intermittent", "irregular"], ant: ["constant", "regular"] },
  { n: 181, word: "strident", pos: "adjective", pron: "STRY-dunt", def: "Loud and harsh; presenting a point forcefully.", ex: "The strident alarm woke the whole building.", syn: ["harsh", "shrill", "forceful"], ant: ["soft", "gentle"] },
  { n: 182, word: "subside", pos: "verb", pron: "sub-SYDE", def: "To become less intense or severe.", ex: "Wait for the swelling to subside before you walk on that ankle.", syn: ["abate", "diminish", "lessen"], ant: ["increase", "intensify"] },
  { n: 183, word: "substantiate", pos: "verb", pron: "sub-STAN-shee-ayt", def: "To provide evidence to support or prove.", ex: "Can you substantiate that claim with a source?", syn: ["support", "verify", "corroborate"], ant: ["disprove", "refute"] },
  { n: 184, word: "succinct", pos: "adjective", pron: "suk-SINGKT", def: "Briefly and clearly expressed.", ex: "Her succinct summary fit on a single index card.", syn: ["concise", "brief", "to the point"], ant: ["wordy", "rambling"] },
  { n: 185, word: "superficial", pos: "adjective", pron: "soo-pur-FISH-ul", def: "Existing only on the surface; not thorough or deep.", ex: "The scratch was superficial and healed in a day.", syn: ["shallow", "surface", "cursory"], ant: ["deep", "thorough"] },
  { n: 186, word: "superfluous", pos: "adjective", pron: "soo-PUR-floo-us", def: "More than is needed; unnecessary.", ex: "With GPS on every phone, paper maps seem superfluous to many drivers.", syn: ["unnecessary", "excessive", "redundant"], ant: ["necessary", "essential"] },
  { n: 187, word: "surpass", pos: "verb", pron: "sur-PASS", def: "To exceed or be greater than.", ex: "Ticket sales surpassed even the most optimistic predictions.", syn: ["exceed", "outdo", "beat"], ant: ["fall short", "trail"] },
  { n: 188, word: "surreptitious", pos: "adjective", pron: "sur-up-TISH-us", def: "Kept secret because it would not be approved of.", ex: "He took a surreptitious bite of cake before dinner.", syn: ["secret", "sneaky", "furtive"], ant: ["open", "blatant"] },
  { n: 189, word: "taciturn", pos: "adjective", pron: "TAS-ih-turn", def: "Reserved and saying little in conversation.", ex: "The taciturn farmer answered most questions with a nod.", syn: ["quiet", "reticent", "uncommunicative"], ant: ["talkative", "garrulous"], root: "Latin tacitus = silent", note: "Usually describes people, not things." },
  { n: 190, word: "terse", pos: "adjective", pron: "TURS", def: "Using few words, sometimes to the point of rudeness.", ex: "Her terse reply, \"No,\" ended the conversation.", syn: ["curt", "brief", "abrupt"], ant: ["wordy", "long-winded"], note: "Usually describes what someone says or writes, not the person." },
  { n: 191, word: "transient", pos: "adjective; also noun", pron: "TRAN-shunt", def: "Lasting only a short time; a person passing through a place.", ex: "The side effects of the vaccine are mild and transient.", syn: ["temporary", "fleeting", "short-lived"], ant: ["permanent", "lasting"] },
  { n: 192, word: "turbulent", pos: "adjective", pron: "TUR-byuh-lunt", def: "Characterized by conflict, disorder, or confusion.", ex: "The plane shook as it flew through turbulent air.", syn: ["stormy", "chaotic", "unstable"], ant: ["calm", "peaceful"], root: "turb- = turmoil, confusion" },
  { n: 193, word: "undermine", pos: "verb", pron: "un-dur-MYNE", def: "To weaken gradually or secretly.", ex: "Constant interruptions undermined his confidence during the presentation.", syn: ["weaken", "sabotage", "erode"], ant: ["strengthen", "support"] },
  { n: 194, word: "usurp", pos: "verb", pron: "yoo-SURP", def: "To take a position of power illegally or by force.", ex: "The general tried to usurp control of the country.", syn: ["seize", "take over", "commandeer"], ant: ["surrender", "relinquish"] },
  { n: 195, word: "vacillate", pos: "verb", pron: "VAS-uh-layt", def: "To waver between different opinions or actions.", ex: "I vacillated between pizza and tacos for twenty minutes.", syn: ["waver", "hesitate", "dither"], ant: ["decide", "commit"] },
  { n: 196, word: "venerate", pos: "verb", pron: "VEN-uh-rayt", def: "To regard with great respect.", ex: "Many cultures venerate their elders.", syn: ["revere", "honor", "worship"], ant: ["scorn", "despise"] },
  { n: 197, word: "verbose", pos: "adjective", pron: "vur-BOHS", def: "Using more words than needed.", ex: "The verbose instructions took three pages to explain how to plug in a lamp.", syn: ["wordy", "long-winded", "rambling"], ant: ["concise", "succinct"], root: "verb- = word" },
  { n: 198, word: "volatile", pos: "adjective", pron: "VOL-uh-tul", def: "Liable to change rapidly and unpredictably; explosive.", ex: "Gas prices have been volatile all year.", syn: ["unstable", "unpredictable", "explosive"], ant: ["stable", "steady"] },
  { n: 199, word: "whimsical", pos: "adjective", pron: "WIM-zih-kul", def: "Playfully quaint or fanciful, especially in an appealing way.", ex: "The children's book had whimsical drawings of dancing teapots.", syn: ["fanciful", "playful", "quirky"], ant: ["serious", "practical"] },
  { n: 200, word: "zealot", pos: "noun", pron: "ZEL-ut", def: "A person who is fanatical in pursuit of their ideals.", ex: "He's a fitness zealot who works out twice a day, even on holidays.", syn: ["fanatic", "extremist", "radical"], ant: ["moderate", "skeptic"] },
];
